content:
I reproduced the client-error retry bug and restricted the predicate to HTTP 429 or the inclusive 500–599 range. No tests or dependencies changed. Candidate patch: demo/solution.patch
SHA-256: 2714852c2b1a12653b3a97b0d2f93d0dc2800bca9c5c1d4b86a543553b1b2847

diff --git a/src/retry.ts b/src/retry.ts
--- a/src/retry.ts
+++ b/src/retry.ts
@@ -1,5 +1,5 @@
 /** Whether an HTTP response should be retried by our API client. */
 export function shouldRetry(status: number): boolean {
   // Only rate limits (429) and server failures (500–599) are retryable.
-  return status >= 400;
+  return status === 429 || (status >= 500 && status <= 599);
 }
